		this.identity		= identity;
		this.projector 		= new DeviceModelEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(DeviceModelRepository.class) );
		this.validator		= applicationContext.getBean(DeviceModelValidator.class) ;
